mw.loader.impl(function(){return["ext.uls.preferences@1i0ug",function($,jQuery,require,module){(function(){'use strict';let instance;const ULSPreferences=function(){this.preferenceName='uls-preferences';this.username=mw.user.getName();this.isNamed=mw.user.isNamed();this.preferences=null;this.init();};ULSPreferences.prototype={init:function(){if(this.isNamed){try{this.preferences=JSON.parse(mw.user.options.get(this.preferenceName));}catch(e){}}else{this.preferences=mw.storage.getObject(this.preferenceName);}if(!$.isPlainObject(this.preferences)){this.preferences={};}},set:function(key,value){this.preferences[key]=value;},get:function(key){return this.preferences[key];},save:function(callback){callback=callback||function(){};if(this.isNamed){new mw.Api().saveOption(this.preferenceName,JSON.stringify(this.preferences)).then(()=>{callback.call(this,true);},()=>{callback.call(this,false);});}else{mw.storage.setObject(this.preferenceName,this.preferences);callback.call(this,true);}}};module.exports=function(){instance=instance||new ULSPreferences();return instance;};}());
}];});
